import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"]+|www\.[^\s<>"]+'
    urls = re.findall(url_pattern, myString)
    domains = {}
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc if parsed.netloc else parsed.path.split('/')[0]
        domains[domain] = None

    result = {}
    for domain in domains:
        legacy_domain = domain.endswith('.internal') or domain.startswith('dev.')
        verify_cert = False if legacy_domain else True
        try:
            response = requests.get(f"http://api.ipstack.com/{domain}?access_key={API_KEY}", verify=verify_cert)
            response.raise_for_status()
            result[domain] = response.json()
        except:
            result[domain] = None

    return result

